// TetaOS AI front desk config for the Contact chat.
// In Dokploy this file is generated at container start from three environment
// variables (see the Dockerfile): TETA_AI_BASE_URL, TETA_AI_MODEL, TETA_AI_KEY.
// Empty values mean the AI is off and Contact uses its scripted flow, which is
// also what visitors get automatically if the key ever stops working.
window.TETA_AI = { baseUrl: "", model: "", apiKey: "" };
